import { dispatch, hookAgent } from "./helpers/hooks_fixture.js";

test("probe1", async () => {
  const home = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "p1-home-")));
  process.env.HOME = home;
  const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), "p1-st-"));
  const store = triggerTrustStorePath();
  fs.mkdirSync(path.dirname(store), { recursive: true });
  const orig = '{"version":1,"entries":[]}\n';
  fs.writeFileSync(store, orig, { mode: 0o600 });
  const repo = fs.realpathSync(makeRepo({ "a.txt": "x\n" }));
  fs.symlinkSync(store, path.join(repo, "innocent.json"));
  fs.symlinkSync(path.dirname(store), path.join(repo, "cfg"));
  fs.linkSync(store, path.join(home, "hard.json"));
  const forged = '{"version":1,"entries":[{"x":1}]}\n';
  for (const ws of [home, path.join(home, ".config", "nexus"), repo]) {
    const agent = hookAgent({ repo: ws, stateDir, mode: "auto", fullAccess: true });
    const sm = (agent as any).bridge.getSecurityManager();
    const rels = ws === home ? [".config/nexus/trigger_trust.json", "./.config/../.config/nexus/trigger_trust.json", "hard.json", ".config/nexus/TRIGGER_TRUST.JSON", ".config/nexus/Trigger_Trust.json"]
      : ws === repo ? ["innocent.json", "cfg/trigger_trust.json", path.relative(repo, store), store]
      : ["trigger_trust.json", "../nexus/trigger_trust.json", store, "./trigger_trust.json"];
    for (const t of rels) {
      const prot = sm.isPathProtected(t).protected;
      const res: string[] = [];
      for (const [tool, args] of [["write_file", { path: t, content: forged }], ["edit_file", { path: t, old_content: orig.trim(), new_content: forged.trim() }], ["delete_file", { path: t }], ["patch_file", { path: t, patch: `--- a/${t}\n+++ b/${t}\n@@ -1 +1 @@\n-${orig.trim()}\n+${forged.trim()}\n` }]] as const) {
        const r = await dispatch(agent, tool, args as any);
        res.push(`${tool}:${r.success ? "OK!!" : "refused"}`);
      }
      console.log(`WS=${ws === home ? "HOME" : ws === repo ? "repo" : "cfg"} ${t} protected=${prot} ${res.join(" ")} storeIntact=${fs.existsSync(store) && fs.readFileSync(store, "utf8") === orig}`);
      if (!fs.existsSync(store) || fs.readFileSync(store, "utf8") !== orig) fs.writeFileSync(store, orig, { mode: 0o600 });
    }
    agent.shutdown();
  }
});
EOF
