content.content:
  1	/**
  2	 * BG-3 trust and abuse model: rate limiting and quarantine for event triggers.
  3	 *
  4	 * Rate limits live on each trigger spec (trigger_spec.ts: `rate.maxPerMinute / maxPerHour / maxPerDay`) and are
  5	 * enforced here per trigger (workspace real path + id) and per workspace. A firer calls
  6	 * `WorkspaceRateLimiter.checkAndRecord` before starting a trigger run; when it returns denied the run never starts.
  7	 * Call it AFTER the caller is authenticated and BEFORE the body is parsed: an unauthenticated caller must not be able
  8	 * to quarantine a trigger.
  9	 *
 10	 * What is recorded: only ADMITTED firings, as epoch milliseconds (numbers, never strings re-parsed per call). A denied
 11	 * attempt is not recorded, so denials never extend a lockout (one probe every 30 minutes cannot keep a 1/day trigger
 12	 * locked beyond its day) and a flood of denials costs O(log n) and no memory.
 13	 *
 14	 * Quarantine: a trigger that fails its own rate limit, crashes, or is denied by the gates N times in a row is
 15	 * quarantined for a cooldown. While quarantined, every firing is denied immediately.
 16	 *
 17	 * Bounds (all enforced, none configurable by a spec):
 18	 *   - a trigger's window holds at most `rate.maxPerDay` (<= 100,000) timestamps, and 24 h of them at most;
 19	 *   - `WorkspaceRateLimiter` keeps at most 1,024 per-trigger limiters (least-recently-used eviction) and 256
 20	 *     workspace windows. Eviction FAILS CLOSED in the way that matters: an evicted limiter restarts with an empty
 21	 *     window (bounded by the workspace cap, which is a separate structure), but a quarantine never lives only in
 22	 *     the limiter: it is mirrored in a separate map of at most 4,096 live quarantines and restored on re-creation.
 23	 *     When that map is full of live quarantines a trigger without one is denied ("limiter state full") rather than
 24	 *     admitted.
 25	 *
 26	 * State here is in-process. Persisting it is the firer's job; `restore()` validates every field and, on ANY invalid
 27	 * field, puts the limiter into quarantine-until-an-operator-releases-it instead of admitting. The firer must add the
 28	 * file it persists to `DEFAULT_PROTECTED_PATHS` in security.ts (an agent that can rewrite it can reset the limits).
 29	 */
 30	
 31	import * as path from "node:path";
 32	import { TRIGGER_RATE_CEILING, validTriggerRate, type TriggerRate } from "./trigger_spec.js";
 33	
 34	const MINUTE_MS = 60 * 1000;
 35	const HOUR_MS = 60 * MINUTE_MS;
 36	const DAY_MS = 24 * HOUR_MS;
 37	
 38	/** Epoch bounds a restored timestamp must fall in (2020-01-01 .. 2200-01-01). */
 39	export const MIN_EPOCH_MS = Date.UTC(2020, 0, 1);
 40	export const MAX_EPOCH_MS = Date.UTC(2200, 0, 1);
 41	
 42	export const DEFAULT_QUARANTINE_FAILURES = 3;
 43	export const DEFAULT_QUARANTINE_COOLDOWN_MINUTES = 15;
 44	export const MAX_LIMITERS = 1024;
 45	export const MAX_WORKSPACE_WINDOWS = 256;
 46	export const MAX_QUARANTINES = 4096;
 47	const MAX_REASON = 200;
 48	const MAX_FAILURES_LIMIT = 1000;
 49	
 50	/** A quarantined trigger: no firing is admitted until `until` (epoch ms) passes, or, with `operatorClear`, until an
 51	 * operator releases it. */
 52	export interface TriggerQuarantine {
 53	  /** Epoch ms after which the trigger may fire again (`MAX_EPOCH_MS` when `operatorClear`). */
 54	  until: number;
 55	  /** Why it was quarantined. */
 56	  reason: string;
 57	  /** Consecutive failures that led to this. */
 58	  failures: number;
 59	  /** Only `releaseQuarantine()` ends this quarantine; the clock does not. Set when restored state was invalid. */
 60	  operatorClear?: boolean;
 61	}
 62	
 63	export interface RateLimitDecision {
 64	  admitted: boolean;
 65	  /** Why denied, when `admitted` is false. */
 66	  reason?: string;
 67	  /** Set when the trigger is (now) quarantined. */
 68	  quarantined?: TriggerQuarantine;
 69	}
 70	
 71	export interface TriggerLimiterSnapshot {
 72	  rate: TriggerRate;
 73	  /** Epoch ms of each admitted firing in the last day, ascending. */
 74	  admittedAt: number[];
 75	  quarantined?: TriggerQuarantine;
 76	  consecutiveFailures: number;
 77	}
 78	
 79	const isRecord = (value: unknown): value is Record<string, unknown> =>
 80	  Boolean(value) && typeof value === "object" && !Array.isArray(value);
 81	
 82	const onlyKeys = (value: Record<string, unknown>, allowed: readonly string[]): boolean =>
 83	  Object.keys(value).every((key) => allowed.includes(key));
 84	
 85	const isEpoch = (value: unknown): value is number =>
 86	  typeof value === "number" && Number.isInteger(value) && value >= MIN_EPOCH_MS && value <= MAX_EPOCH_MS;
 87	
 88	/** Index of the first element of the ascending `values` that is >= `target`. */
 89	function lowerBound(values: readonly number[], target: number): number {
 90	  let low = 0;
 91	  let high = values.length;
 92	  while (low < high) {
 93	    const mid = (low + high) >>> 1;
 94	    if (values[mid]! < target) low = mid + 1; else high = mid;
 95	  }
 96	  return low;
 97	}
 98	
 99	/** Drops timestamps older than a day (from the front of the ascending array). */
100	function pruneDay(values: number[], now: number): void {
101	  const cut = lowerBound(values, now - DAY_MS);
102	  if (cut > 0) values.splice(0, cut);
103	}
104	
105	/** How many of the ascending `values` fall in the last minute / hour / day before `now`. */
106	function countWindows(values: readonly number[], now: number): { minute: number; hour: number; day: number } {
107	  const total = values.length;
108	  return {
109	    minute: total - lowerBound(values, now - MINUTE_MS),
110	    hour: total - lowerBound(values, now - HOUR_MS),
111	    day: total - lowerBound(values, now - DAY_MS),
112	  };
113	}
114	
115	function insertAscending(values: number[], at: number): void {
116	  if (values.length === 0 || at >= values[values.length - 1]!) values.push(at);
117	  else values.splice(lowerBound(values, at), 0, at);
118	}
119	
120	/** A rate limiter for one trigger. Holds the sliding window of admitted firings and the quarantine. */
121	export class TriggerRateLimiter {
122	  private rate: TriggerRate;
123	  private readonly maxFailures: number;
124	  private readonly cooldownMs: number;
125	  private admittedAt: number[] = [];
126	  private quarantined: TriggerQuarantine | undefined;
127	  private consecutiveFailures = 0;
128	
129	  constructor(rate: TriggerRate, options?: { maxFailures?: number; cooldownMinutes?: number }) {
130	    const valid = validTriggerRate(rate);
131	    if (!valid) throw new Error("TriggerRateLimiter: the rate is not one a trigger spec may carry");
132	    this.rate = valid;
133	    this.maxFailures = options?.maxFailures ?? DEFAULT_QUARANTINE_FAILURES;
134	    this.cooldownMs = (options?.cooldownMinutes ?? DEFAULT_QUARANTINE_COOLDOWN_MINUTES) * MINUTE_MS;
135	  }
136	
137	  /** The rate the limiter enforces. */
138	  public currentRate(): TriggerRate {
139	    return { ...this.rate };
140	  }
141	
142	  /** Re-applies a (re-approved) spec's rate; the window and the quarantine are kept. */
143	  public setRate(rate: TriggerRate): void {
144	    const valid = validTriggerRate(rate);
145	    if (!valid) throw new Error("TriggerRateLimiter.setRate: the rate is not one a trigger spec may carry");
146	    this.rate = valid;
147	  }
148	
149	  /** The live quarantine, if any (an expired one is released first). */
150	  public quarantineState(now: Date): TriggerQuarantine | undefined {
151	    return this.activeQuarantine(now.getTime());
152	  }
153	
154	  /** Puts a quarantine back (after the limiter was evicted and re-created). */
155	  public adoptQuarantine(quarantine: TriggerQuarantine): void {
156	    this.quarantined = quarantine;
157	    this.consecutiveFailures = Math.min(quarantine.failures, this.maxFailures);
158	  }
159	
160	  /**
161	   * Call before starting a trigger run. Returns whether it is admitted; an admission is recorded, a denial is not.
162	   * `gate` is consulted last, after the trigger's own limits pass (the workspace cap); a gate denial is not this
163	   * trigger's failure and does not count toward its quarantine.
164	   */
165	  public checkAndRecord(now: Date, gate?: (nowMs: number) => string | undefined): RateLimitDecision {
166	    const t = now.getTime();
167	    if (!Number.isFinite(t)) return { admitted: false, reason: "invalid clock" };
168	
169	    const quarantine = this.activeQuarantine(t);
170	    if (quarantine) return { admitted: false, reason: "quarantined", quarantined: quarantine };
171	
172	    pruneDay(this.admittedAt, t);
173	    const counts = countWindows(this.admittedAt, t);
174	    if (counts.minute >= this.rate.maxPerMinute || counts.hour >= this.rate.maxPerHour || counts.day >= this.rate.maxPerDay)
175	      return this.fail(t, "rate limit", "rate limit exceeded");
176	
177	    const gated = gate?.(t);
178	    if (gated) return { admitted: false, reason: gated };
179	
180	    insertAscending(this.admittedAt, t);
181	    this.consecutiveFailures = 0;
182	    return { admitted: true };
183	  }
184	
185	  /** Record an externally-reported failure (the run was denied by the gates, crashed, or produced no progress) so it
186	   * counts toward quarantine. The firer calls this when a run ends without completing. Not recorded in the window. */
187	  public recordFailure(now: Date, reason: string): RateLimitDecision {
188	    const t = now.getTime();
189	    if (!Number.isFinite(t)) return { admitted: false, reason: "invalid clock" };
190	    const quarantine = this.activeQuarantine(t);
191	    if (quarantine) return { admitted: false, reason: "quarantined", quarantined: quarantine };
192	    return this.fail(t, reason, reason);
193	  }
194	
195	  /** Release a quarantine (the operator's action; also the only way out of a fail-closed restore). */
196	  public releaseQuarantine(): void {
197	    this.quarantined = undefined;
198	    this.consecutiveFailures = 0;
199	  }
200	
201	  public snapshot(): TriggerLimiterSnapshot {
202	    return {
203	      rate: { ...this.rate },
204	      admittedAt: [...this.admittedAt],
205	      ...(this.quarantined ? { quarantined: { ...this.quarantined } } : {}),
206	      consecutiveFailures: this.consecutiveFailures,
207	    };
208	  }
209	
210	  /**
211	   * Restore persisted state. Every field is validated (numbers finite, integral and in range; the rate one a spec
212	   * may carry; arrays bounded by the rate; no extra or missing keys). On ANY invalid field nothing from `raw` is
213	   * used and the limiter is quarantined until `releaseQuarantine()`: tampered state never admits. Returns whether
214	   * the state was accepted.
215	   */
216	  public restore(raw: unknown): boolean {
217	    const problem = this.tryRestore(raw);
218	    if (problem === undefined) return true;
219	    this.admittedAt = [];
220	    this.consecutiveFailures = 0;
221	    this.quarantined = {
222	      until: MAX_EPOCH_MS,
223	      reason: `restored limiter state was invalid (${problem}); an operator must release it`.slice(0, MAX_REASON),
224	      failures: 0,
225	      operatorClear: true,
226	    };
227	    return false;
228	  }
229	
230	  private tryRestore(raw: unknown): string | undefined {
231	    if (!isRecord(raw)) return "not an object";
232	    if (!onlyKeys(raw, ["rate", "admittedAt", "quarantined", "consecutiveFailures"])) return "unexpected key";
233	    const rate = validTriggerRate(raw.rate);
234	    if (!rate) return "rate";
235	    const stamps = raw.admittedAt;
236	    if (!Array.isArray(stamps) || stamps.length > rate.maxPerDay || stamps.length > TRIGGER_RATE_CEILING.maxPerDay)
237	      return "admittedAt";
238	    if (!stamps.every(isEpoch)) return "admittedAt entry";
239	    const failures = raw.consecutiveFailures;
240	    if (typeof failures !== "number" || !Number.isInteger(failures) || failures < 0 || failures > this.maxFailures)
241	      return "consecutiveFailures";
242	    let quarantined: TriggerQuarantine | undefined;
243	    if (raw.quarantined !== undefined) {
244	      quarantined = validQuarantine(raw.quarantined);
245	      if (!quarantined) return "quarantined";
246	    }
247	    this.rate = rate;
248	    this.admittedAt = [...(stamps as number[])].sort((a, b) => a - b);
249	    this.consecutiveFailures = failures;
250	    this.quarantined = quarantined;
251	    return undefined;
252	  }
253	
254	  private activeQuarantine(nowMs: number): TriggerQuarantine | undefined {
255	    const q = this.quarantined;
256	    if (!q) return undefined;
257	    if (q.operatorClear || nowMs < q.until) return q;
258	    // Cooldown passed: release, reset the failure count.
259	    this.quarantined = undefined;
260	    this.consecutiveFailures = 0;
261	    return undefined;
262	  }
263	
264	  private fail(nowMs: number, reason: string, why: string): RateLimitDecision {
265	    this.consecutiveFailures++;
266	    if (this.consecutiveFailures >= this.maxFailures) {
267	      this.quarantined = {
268	        until: nowMs + this.cooldownMs,
269	        reason: `${why} ${this.maxFailures} times in a row`.slice(0, MAX_REASON),
270	        failures: this.consecutiveFailures,
271	      };
272	      return { admitted: false, reason: "quarantined", quarantined: this.quarantined };
273	    }
274	    return { admitted: false, reason };
275	  }
276	}
277	
278	function validQuarantine(raw: unknown): TriggerQuarantine | undefined {
279	  if (!isRecord(raw) || !onlyKeys(raw, ["until", "reason", "failures", "operatorClear"])) return undefined;
280	  const { until, reason, failures, operatorClear } = raw;
281	  if (!isEpoch(until)) return undefined;
282	  if (typeof reason !== "string" || reason.length > MAX_REASON) return undefined;
283	  if (typeof failures !== "number" || !Number.isInteger(failures) || failures < 0 || failures > MAX_FAILURES_LIMIT) return undefined;
284	  if (operatorClear !== undefined && operatorClear !== true) return undefined;
285	  return { until, reason, failures, ...(operatorClear ? { operatorClear: true } : {}) };
286	}
287	
288	/** Default workspace-level caps: a workspace cannot flood the runner regardless of how many triggers it has. */
289	export const DEFAULT_WORKSPACE_LIMITS = { maxPerMinute: 30, maxPerHour: 300, maxPerDay: 2000 };
290	
291	export interface WorkspaceRateLimiterSnapshot {
292	  perTrigger: Array<[string, TriggerLimiterSnapshot]>;
293	  quarantines: Array<[string, TriggerQuarantine]>;
294	  workspaceAdmits: Array<[string, number[]]>;
295	}
296	
297	/**
298	 * The limiter the firer calls: one `TriggerRateLimiter` per (workspace real path, trigger id), plus a cap per
299	 * workspace that every trigger in it shares. `checkAndRecord` admits only when the trigger's own limits AND the
300	 * workspace cap both allow, and records the admission in both.
301	 */
302	export class WorkspaceRateLimiter {
303	  private readonly limiters = new Map<string, TriggerRateLimiter>();
304	  private readonly quarantines = new Map<string, TriggerQuarantine>();
305	  private readonly workspaceAdmits = new Map<string, number[]>();
306	  private readonly limits: TriggerRate;
307	  private locked: string | undefined;
308	
309	  constructor(
310	    workspaceLimits: TriggerRate = DEFAULT_WORKSPACE_LIMITS,
311	    private readonly caps: { maxLimiters?: number; maxWorkspaces?: number; maxQuarantines?: number } = {},
312	  ) {
313	    const limits = validTriggerRate(workspaceLimits);
314	    if (!limits) throw new Error("WorkspaceRateLimiter: the workspace limits are not valid rates");
315	    this.limits = limits;
316	  }
317	
318	  private get maxLimiters(): number { return this.caps.maxLimiters ?? MAX_LIMITERS; }
319	  private get maxWorkspaces(): number { return this.caps.maxWorkspaces ?? MAX_WORKSPACE_WINDOWS; }
320	  private get maxQuarantines(): number { return this.caps.maxQuarantines ?? MAX_QUARANTINES; }
321	
322	  /**
323	   * Whether the firing of `triggerId` (as approved, with `rate`) in `workspace` (its real path) is admitted at `now`.
324	   * A re-approved spec that changed the rate takes effect here (the window and quarantine are kept).
325	   */
326	  public checkAndRecord(workspace: string, triggerId: string, rate: TriggerRate, now: Date): RateLimitDecision {
327	    const t = now.getTime();
328	    if (!Number.isFinite(t)) return { admitted: false, reason: "invalid clock" };
329	    if (this.locked) return { admitted: false, reason: `limiter state invalid: ${this.locked}` };
330	    const key = limiterKey(workspace, triggerId);
331	
332	    if (this.quarantines.size >= this.maxQuarantines) this.purgeExpiredQuarantines(t);
333	    if (this.quarantines.size >= this.maxQuarantines && !this.quarantines.has(key))
334	      return { admitted: false, reason: "limiter state full" };
335	
336	    const limiter = this.limiterFor(workspace, triggerId, rate);
337	    const decision = limiter.checkAndRecord(now, (nowMs) => this.workspaceReason(workspace, nowMs));
338	    if (decision.admitted) this.recordWorkspaceAdmission(workspace, t);
339	    this.mirrorQuarantine(key, limiter, now);
340	    return decision;
341	  }
342	
343	  /** Records a failure the firer observed (crash, gate denial). Counts toward the trigger's quarantine. */
344	  public recordFailure(workspace: string, triggerId: string, rate: TriggerRate, now: Date, reason: string): RateLimitDecision {
345	    const limiter = this.limiterFor(workspace, triggerId, rate);
346	    const decision = limiter.recordFailure(now, reason);
347	    this.mirrorQuarantine(limiterKey(workspace, triggerId), limiter, now);
348	    return decision;
349	  }
350	
351	  /** The operator's release of one trigger's quarantine (the firer's `nexus triggers release`). */
352	  public releaseQuarantine(workspace: string, triggerId: string): void {
353	    const key = limiterKey(workspace, triggerId);
354	    this.limiters.get(key)?.releaseQuarantine();
355	    this.quarantines.delete(key);
356	  }
357	
358	  /** The operator's release of a fail-closed restore of the whole limiter. */
359	  public clearLock(): void {
360	    this.locked = undefined;
361	  }
362	
363	  /** Whether the workspace is within its own caps right now (independent of any single trigger). */
364	  public workspaceWithinLimits(workspace: string, now: Date): boolean {
365	    const t = now.getTime();
366	    return Number.isFinite(t) && this.workspaceReason(workspace, t) === undefined;
367	  }
368	
369	  /** Number of per-trigger limiters held (bounded by `MAX_LIMITERS`). */
370	  public size(): number {
371	    return this.limiters.size;
372	  }
373	
374	  public snapshot(): WorkspaceRateLimiterSnapshot {
375	    return {
376	      perTrigger: [...this.limiters.entries()].map(([key, limiter]) => [key, limiter.snapshot()]),
377	      quarantines: [...this.quarantines.entries()].map(([key, q]) => [key, { ...q }]),
378	      workspaceAdmits: [...this.workspaceAdmits.entries()].map(([workspace, stamps]) => [workspace, [...stamps]]),
379	    };
380	  }
381	
382	  /**
383	   * Restore persisted state, validating everything. A bad per-trigger entry is quarantined until released; a bad
384	   * container, key, workspace window or quarantine locks the whole limiter (every firing denied) until `clearLock()`.
385	   * Returns whether everything was accepted.
386	   */
387	  public restore(raw: unknown): boolean {
388	    this.limiters.clear();
389	    this.quarantines.clear();
390	    this.workspaceAdmits.clear();
391	    this.locked = undefined;
392	    const lock = (why: string): false => {
393	      this.limiters.clear();
394	      this.quarantines.clear();
395	      this.workspaceAdmits.clear();
396	      this.locked = why;
397	      return false;
398	    };
399	    if (!isRecord(raw) || !onlyKeys(raw, ["perTrigger", "quarantines", "workspaceAdmits"])) return lock("not a limiter snapshot");
400	    const { perTrigger, quarantines, workspaceAdmits } = raw;
401	    if (!Array.isArray(perTrigger) || !Array.isArray(quarantines) || !Array.isArray(workspaceAdmits)) return lock("missing section");
402	    if (perTrigger.length > this.maxLimiters || quarantines.length > this.maxQuarantines || workspaceAdmits.length > this.maxWorkspaces)
403	      return lock("too many entries");
404	
405	    let allValid = true;
406	    for (const pair of perTrigger) {
407	      if (!Array.isArray(pair) || pair.length !== 2 || !validKey(pair[0])) return lock("limiter entry");
408	      const snapshotRate = isRecord(pair[1]) ? validTriggerRate(pair[1].rate) : undefined;
409	      const limiter = new TriggerRateLimiter(snapshotRate ?? { maxPerMinute: 1, maxPerHour: 1, maxPerDay: 1 });
410	      if (!limiter.restore(pair[1])) allValid = false;
411	      this.limiters.set(pair[0], limiter);
412	      const q = limiter.quarantineState(new Date(MIN_EPOCH_MS));
413	      if (q) this.quarantines.set(pair[0], q);
414	    }
415	    for (const pair of quarantines) {
416	      if (!Array.isArray(pair) || pair.length !== 2 || !validKey(pair[0])) return lock("quarantine entry");
417	      const q = validQuarantine(pair[1]);
418	      if (!q) return lock("quarantine entry");
419	      this.quarantines.set(pair[0], q);
420	    }
421	    for (const pair of workspaceAdmits) {
422	      if (!Array.isArray(pair) || pair.length !== 2 || typeof pair[0] !== "string" || pair[0].length === 0 || pair[0].length > 4096) return lock("workspace entry");
423	      const stamps = pair[1];
424	      if (!Array.isArray(stamps) || stamps.length > this.limits.maxPerDay || !stamps.every(isEpoch)) return lock("workspace window");
425	      this.workspaceAdmits.set(pair[0], [...(stamps as number[])].sort((a, b) => a - b));
426	    }
427	    return allValid;
428	  }
429	
430	  /** Get or create the limiter for (`workspace`, `triggerId`), at the spec's current `rate`. */
431	  private limiterFor(workspace: string, triggerId: string, rate: TriggerRate): TriggerRateLimiter {
432	    const key = limiterKey(workspace, triggerId);
433	    let limiter = this.limiters.get(key);
434	    if (limiter) {
435	      this.limiters.delete(key); // least-recently-used order
436	    } else {
437	      limiter = new TriggerRateLimiter(rate);
438	      const surviving = this.quarantines.get(key);
439	      if (surviving) limiter.adoptQuarantine(surviving);
440	    }
441	    limiter.setRate(rate);
442	    this.limiters.set(key, limiter);
443	    while (this.limiters.size > this.maxLimiters) {
444	      const oldest = this.limiters.keys().next().value as string;
445	      this.limiters.delete(oldest); // a live quarantine survives in `this.quarantines`
446	    }
447	    return limiter;
448	  }
449	
450	  private mirrorQuarantine(key: string, limiter: TriggerRateLimiter, now: Date): void {
451	    const q = limiter.quarantineState(now);
452	    if (q) this.quarantines.set(key, q); else this.quarantines.delete(key);
453	  }
454	
455	  private purgeExpiredQuarantines(nowMs: number): void {
456	    for (const [key, q] of this.quarantines) if (!q.operatorClear && nowMs >= q.until) this.quarantines.delete(key);
457	  }
458	
459	  private workspaceReason(workspace: string, nowMs: number): string | undefined {
460	    const stamps = this.workspaceAdmits.get(workspace);
461	    if (!stamps) return undefined;
462	    pruneDay(stamps, nowMs);
463	    const counts = countWindows(stamps, nowMs);
464	    return counts.minute >= this.limits.maxPerMinute || counts.hour >= this.limits.maxPerHour || counts.day >= this.limits.maxPerDay
465	      ? "workspace rate limit"
466	      : undefined;
467	  }
468	
469	  private recordWorkspaceAdmission(workspace: string, nowMs: number): void {
470	    let stamps = this.workspaceAdmits.get(workspace);
471	    if (stamps) this.workspaceAdmits.delete(workspace); else stamps = [];
472	    insertAscending(stamps, nowMs);
473	    this.workspaceAdmits.set(workspace, stamps);
474	    while (this.workspaceAdmits.size > this.maxWorkspaces) this.workspaceAdmits.delete(this.workspaceAdmits.keys().next().value as string);
475	  }
476	}
477	
478	function limiterKey(workspace: string, triggerId: string): string {
479	  if (!workspace || !path.isAbsolute(workspace)) throw new Error("the workspace must be an absolute real path");
480	  return `${workspace}\u0000${triggerId}`;
481	}
482	
483	function validKey(value: unknown): value is string {
484	  return typeof value === "string" && value.length <= 4200 && /^[^\0]+\0[a-z0-9][a-z0-9-]{0,62}$/.test(value);
485	}

