171	
172	    pruneDay(this.admittedAt, t);
173	    const counts = countWindows(this.admittedAt, t);
174	    if (counts.minute >= this.rate.maxPerMinute || counts.hour >= this.rate.maxPerHour || counts.day >= this.rate.maxPerDay)
