185	  /** Record an externally-reported failure (the run was denied by the gates, crashed, or produced no progress) so it
186	   * counts toward quarantine. The firer calls this when a run ends without completing. Not recorded in the window. */
187	  public recordFailure(now: Date, reason: string): RateLimitDecision {
188	    const t = now.getTime();
189	    if (!Number.isFinite(t)) return { admitted: false, reason: "invalid clock" };
190	    const quarantine = this.activeQuarantine(t);
