453	  }
454	
455	  private purgeExpiredQuarantines(nowMs: number): void {
456	    for (const [key, q] of this.quarantines) if (!q.operatorClear && nowMs >= q.until) this.quarantines.delete(key);
457	  }
458	
459	  private workspaceReason(workspace: string, nowMs: number): string | undefined {
460	    const stamps = this.workspaceAdmits.get(workspace);
461	    if (!stamps) return undefined;
462	    pruneDay(stamps, nowMs);
463	    const counts = countWindows(stamps, nowMs);
464	    return counts.minute >= this.limits.maxPerMinute || counts.hour >= this.limits.maxPerHour || counts.day >= this.limits.maxPerDay
465	      ? "workspace rate limit"
466	      : undefined;
467	  }
468	
469	  private recordWorkspaceAdmission(workspace: string, nowMs: number): void {
470	    let stamps = this.workspaceAdmits.get(workspace);
471	    if (stamps) this.workspaceAdmits.delete(workspace); else stamps = [];
472	    insertAscending(stamps, nowMs);
473	    this.workspaceAdmits.set(workspace, stamps);
474	    while (this.workspaceAdmits.size > this.maxWorkspaces) this.workspaceAdmits.delete(this.workspaceAdmits.keys().next().value as string);
475	  }
476	}
477	
478	function limiterKey(workspace: string, triggerId: string): string {
479	  if (!workspace || !path.isAbsolute(workspace)) throw new Error("the workspace must be an absolute real path");
480	  return `${workspace}\u0000${triggerId}`;
481	}
482	
483	function validKey(value: unknown): value is string {
484	  return typeof value === "string" && value.length <= 4200 && /^[^\0]+\0[a-z0-9][a-z0-9-]{0,62}$/.test(value);
485	}

